const employeeCodes = items.map(item => item.json["Employee Code"]);
const employeecodesearch = $('Form Trigger').first().json['Employee Code'];

const isExist = employeeCodes.includes(employeecodesearch);

return [{
  json: {
    employeeCodes: employeeCodes,
    employeecodeSearch: employeecodesearch,
    isEmployeeExist: isExist  // Boolean true/false
  }
}];

